import { CONNECT_SCOPES, VIEWER_SCOPES } from 'constants/accessScopes';

export const hasViewerScope = (scopes: string[]): boolean =>
  scopes.some((scope) => (VIEWER_SCOPES as readonly string[]).includes(scope));

export const hasConnectScope = (scopes: string[]): boolean =>
  scopes.some((scope) => (CONNECT_SCOPES as readonly string[]).includes(scope));
